oxy_webhelp_navlinks = {"saphana-d39536e40715":{"topics":[{"title":"Introduction to SAP HANA protection","href":"saas\/saphana_key_features_protection.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e40728","next":"tocId-d39536e40728"},{"title":"SAP HANA protection implementation workflow","shortdesc":"<p class=\"shortdesc\">Protecting SAP HANA databases involves a structured workflow that starts with         planning and preparation, followed by system setup, protection configuration, ongoing         management, and recovery.<\/p>","href":"saas\/saphana_implementation_workflow.html","attributes":{"data-id":"saphana_implementation_workflow"},"menu":{"hasChildren":false},"tocID":"saphana_implementation_workflow-d39536e40782","topics":[]},{"title":"Quick links for SAP HANA protection","shortdesc":"<p class=\"shortdesc\">Immediate access to important tasks and information for SAP HANA setup, daily         operations, and recovery.<\/p>","href":"saas\/saphana_quick_links.html","attributes":{"data-id":"saphana_quick_links"},"menu":{"hasChildren":false},"tocID":"saphana_quick_links-d39536e40793","topics":[]},{"title":"Plan your SAP HANA protection","shortdesc":"<p class=\"shortdesc\">Before setting up SAP HANA protection, it is important that you review the         prerequisites, configure user access, and verify the required permissions in <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/saphana_plan_protection.html","attributes":{"data-id":"saphana_plan_protection"},"menu":{"hasChildren":false},"tocID":"saphana_plan_protection-d39536e40804","next":"saphana_plan_protection-d39536e40804"},{"title":"Set up your SAP HANA system","shortdesc":"<p class=\"shortdesc\">You can set up your SAP HANA system for protection by evaluating your deployment         options, installing Rubrik Backup Service, and adding the SAP HANA host and system to <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/saphana_setup_system.html","attributes":{"data-id":"saphana_setup_system"},"menu":{"hasChildren":false},"tocID":"saphana_setup_system-d39536e40859","next":"saphana_setup_system-d39536e40859"},{"title":"Protect SAP HANA databases","shortdesc":"<p class=\"shortdesc\">You can protect your SAP HANA databases by understanding the protection hierarchy,         reviewing best practices, evaluating protection options, and configuring SLA         Domains.<\/p>","href":"saas\/saphana_protect_databases.html","attributes":{"data-id":"saphana_protect_databases"},"menu":{"hasChildren":false},"tocID":"saphana_protect_databases-d39536e41045","next":"saphana_protect_databases-d39536e41045"},{"title":"Configure SAP HANA storage snapshots","shortdesc":"<p class=\"shortdesc\">Using <span class=\"ph\">RSC<\/span>, you can take storage snapshots of SAP HANA systems running         on an Azure virtual machine and use those snapshots to recover your SAP HANA databases.         Storage snapshots are fast, encrypted, have negligible network load, and capture the entire         data area at a particular point in time.<\/p>","href":"saas\/configure_sap_hana_storage_snapshots.html","attributes":{"data-id":"configure_sap_hana_storage_snapshots"},"menu":{"hasChildren":false},"tocID":"configure_sap_hana_storage_snapshots-d39536e41146","next":"configure_sap_hana_storage_snapshots-d39536e41146"},{"title":"Configure SAP HANA system replication","shortdesc":"<p class=\"shortdesc\">SAP HANA system replication ensures high availability and disaster recovery for your         SAP HANA system by setting up a backup system in the same or a different data center. <span class=\"ph\">RSC<\/span> protects these configurations through SLA Domain policies.<\/p>","href":"saas\/configure_sap_hana_system_replication.html","attributes":{"data-id":"configure_sap_hana_system_replication"},"menu":{"hasChildren":false},"tocID":"configure_sap_hana_system_replication-d39536e41171","next":"configure_sap_hana_system_replication-d39536e41171"},{"title":"Manage SAP HANA data","shortdesc":"<p class=\"shortdesc\">You can manage your SAP HANA data by configuring legal holds, adjusting snapshot         retention, and viewing database details.<\/p>","href":"saas\/saphana_manage_data.html","attributes":{"data-id":"saphana_manage_data"},"menu":{"hasChildren":false},"tocID":"saphana_manage_data-d39536e41254","next":"saphana_manage_data-d39536e41254"},{"title":"Multi-cluster RBS for SAP HANA","shortdesc":"<p class=\"shortdesc\">You can connect an SAP HANA host to multiple Rubrik clusters to enable cross-cluster         database restore without reinstalling the Rubrik Backup Service.<\/p>","href":"saas\/sap_hana_multi_cluster_rbs.html","attributes":{"data-id":"sap_hana_multi_cluster_rbs"},"menu":{"hasChildren":false},"tocID":"sap_hana_multi_cluster_rbs-d39536e41334","topics":[]},{"title":"Recover SAP HANA data","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides various recovery options for SAP HANA databases,         including recovery through <span class=\"ph\">RSC<\/span>, SAP HANA Studio, storage snapshots, and from         archived or replicated snapshots.<\/p>","href":"saas\/saphana_recover_data.html","attributes":{"data-id":"saphana_recover_data"},"menu":{"hasChildren":false},"tocID":"saphana_recover_data-d39536e41346","next":"saphana_recover_data-d39536e41346"}]}};